<!-- --------- новый код chat: остатки материалов отдельно по цехам договора -->
<template><div class="warehouse-page">
    <header class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="fs-5 me-auto mb-0">Склад договора</h2><button class="btn btn-outline-secondary btn-sm" @click="referenceOpen=true">Цеха и единицы</button><button class="btn btn-primary btn-sm" @click="materialForm={material:null}">Добавить материал</button></header>
    <div v-if="error" class="alert alert-danger">{{ error }} <button class="btn btn-link btn-sm" @click="load">Повторить</button></div>
    <div class="row g-2 border rounded-3 p-3 bg-white mx-0 mb-3"><div class="col-md-5"><label class="form-label">Поиск материала</label><input v-model="search" type="search" class="form-control form-control-sm" placeholder="Наименование"></div><div class="col-md-4"><label class="form-label">Цех</label><select v-model="shop" class="form-select form-select-sm"><option :value="0">Все цеха</option><option v-for="s in refs.workshops" :key="s.ID" :value="s.ID">{{ s.name }}</option></select></div><div class="col-md-3"><label class="form-label">Наличие</label><select v-model="availability" class="form-select form-select-sm"><option value="">Все материалы</option><option value="available">В наличии</option><option value="empty">Закончились / нет остатка</option></select></div></div>
    <div v-if="loading" class="text-secondary p-3">Загрузка…</div>
    <div v-else class="border rounded-3 overflow-hidden bg-white table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>№</th><th>Материал</th><th>Цех</th><th>Ед.</th><th>Поступило</th><th>Использовано</th><th>Остаток</th><th>Действия</th></tr></thead><tbody><tr v-for="(m,i) in filtered" :key="m.ID"><td>{{ i+1 }}</td><td>{{ m.name }}</td><td>{{ shopName(m.workshop_id) }}</td><td>{{ unitName(m.unit_id) }}</td><td>{{ quantityDisplay(m.received) }}</td><td>{{ quantityDisplay(m.used) }}</td><td :class="m.balance>0?'text-success':'text-danger'">{{ quantityDisplay(m.balance) }} <span v-if="!m.balance" class="small">нет остатка</span></td><td><div class="d-flex flex-wrap gap-1"><button class="btn btn-outline-primary btn-sm" :disabled="busy" @click="receiptForm={material:m,receipt:null,remove:false}">Приход</button><button class="btn btn-outline-secondary btn-sm" :disabled="busy" @click="history=m">История</button><button class="btn btn-outline-secondary btn-sm" :disabled="busy" @click="materialForm={material:m}" aria-label="Изменить материал"><i class="bi bi-pencil"></i></button><button class="btn btn-outline-danger btn-sm" :disabled="busy" @click="remove(m)" aria-label="Удалить материал"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!filtered.length"><td colspan="8" class="text-secondary p-3">Материалы не найдены.</td></tr></tbody></table></div>
    <WorkOrderReferenceModal v-if="referenceOpen" :agreement-id="agreementID" :refs="refs" @close="referenceOpen=false" @changed="load" />
    <WarehouseMaterialModal v-if="materialForm" :agreement-id="agreementID" :material="materialForm.material" :refs="refs" @close="materialForm=null" @saved="materialForm=null;load()" />
    <WarehouseHistoryModal v-if="history" :agreement-id="agreementID" :material="history" :unit="unitName(history.unit_id)" @close="history=null" @edit="editReceipt" />
    <WarehouseReceiptModal v-if="receiptForm" :agreement-id="agreementID" v-bind="receiptForm" :unit="unitName(receiptForm.material.unit_id)" @close="receiptForm=null" @saved="receiptForm=null;load()" />
</div></template>
<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import api from '../../../api';import WorkOrderReferenceModal from './WorkOrderReferenceModal.vue';import WarehouseMaterialModal from './WarehouseMaterialModal.vue';import WarehouseReceiptModal from './WarehouseReceiptModal.vue';import WarehouseHistoryModal from './WarehouseHistoryModal.vue';import {emptyWorkReferences,quantityDisplay,workError} from './workOrderHelpers';
const route=useRoute(),agreementID=computed(()=>String(route.params.id));const refs=ref(emptyWorkReferences()),materials=ref([]),search=ref(''),shop=ref(0),availability=ref(''),error=ref(''),loading=ref(false),busy=ref(false),referenceOpen=ref(false),materialForm=ref(null),receiptForm=ref(null),history=ref(null);let version=0;
const shopName=id=>refs.value.workshops.find(s=>s.ID===id)?.name||'—';const unitName=id=>refs.value.units.find(u=>u.ID===id)?.name||'';
const filtered=computed(()=>materials.value.filter(m=>(!shop.value||m.workshop_id===shop.value)&&m.name.toLocaleLowerCase('ru').includes(search.value.trim().toLocaleLowerCase('ru'))&&(!availability.value||(availability.value==='available'?m.balance>0:m.balance===0))));
const load=async()=>{const v=++version,id=agreementID.value;loading.value=true;error.value='';try{const [r,m]=await Promise.all([api.get(`/agreements/${id}/work-references`),api.get(`/agreements/${id}/warehouse`)]);if(v!==version)return;refs.value=r.data;materials.value=m.data;}catch(e){if(v===version)error.value=workError(e);}finally{if(v===version)loading.value=false;}};
const editReceipt=(receipt,remove)=>{receiptForm.value={material:history.value,receipt,remove};history.value=null;};
const remove=async m=>{if(busy.value)return;busy.value=true;try{const {data}=await api.get(`/agreements/${agreementID.value}/warehouse/${m.ID}/history`);if(!confirm(`Удалить «${m.name}» в цехе «${shopName(m.workshop_id)}»? Будут удалены ${data.receipts.length} поступлений и ${data.usages.length} строк использования во всех месяцах. Работы сохранятся.`))return;await api.delete(`/agreements/${agreementID.value}/warehouse/${m.ID}`);await load();}catch(e){error.value=workError(e);}finally{busy.value=false;}};
watch(agreementID,()=>{search.value='';shop.value=0;availability.value='';materials.value=[];referenceOpen.value=false;materialForm.value=null;receiptForm.value=null;history.value=null;load();},{immediate:true});onBeforeUnmount(()=>version++);
</script>
<style scoped>.warehouse-page{font-size:13px;} .btn,.form-select,.form-control{font-size:13px;} th,td{padding:10px;} th{background:#f8f9fa;} .table{min-width:850px;}</style>
<!-- --------- конец нового кода chat -->
